struct AulaDeHumanas {
    texto_principal: String,
}
struct AulaDeExatas {
    grafico_complexo: Vec<(f32, f32)>,
}

fn projetar_aula(material: AulaDeHumanas) {
    println!('Exibindo texto: {}', material.texto_principal);
}

fn main() {
    let aula_ple = AulaDeHumanas {
        texto_principal: 'O texto dissertativo argumentativo...'.to_string()
    };
    let aula_me = AulaDeExatas {
        grafico_complexo: vec![(0.1, 0.2), (0.3, 0.4)]
    };

    projetar_aula(aula_ple);
    projetar_aula(aula_me);
}
